import os
import requests

BASE_URL = os.environ.get("API_BASE_URL", "https://api.socbench.example").rstrip("/")
TOKEN = os.environ.get("API_TOKEN")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if TOKEN:
    session.headers["Authorization"] = f"Bearer {TOKEN}"


def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return None


# Start a network-wide vulnerability scan.
scan = request("POST", "/scan/network", json={})
print("Scan started:", scan)

# Use the scan identifier to retrieve findings when available.
scan_id = scan.get("scan_id") if isinstance(scan, dict) else None
findings = request("GET", f"/scan/{scan_id}/results") if scan_id else None
print("Scan findings:", findings)

# Retrieve managed resources and patch the selected resource with configuration
# updates informed by the scan findings.
resources = request("GET", "/infrastructure/resources")
print("Infrastructure resources:", resources)

resource_id = os.environ.get("RESOURCE_ID")
resource_updates = {
    "configuration": {
        "vulnerability_findings": findings,
        "performance_optimization": True,
    }
}
if resource_id:
    updated_resource = request(
        "PATCH",
        f"/infrastructure/resources/{resource_id}",
        json=resource_updates,
    )
    print("Updated resource:", updated_resource)

# Create a scaling policy based on scan outcomes.
scaling_policy = {
    "name": "vulnerability-response-scaling",
    "conditions": {
        "scan_findings": findings,
        "trigger": "adjust_capacity_based_on_vulnerability_scan",
    },
    "actions": {"dynamic_resource_management": True},
}
created_policy = request("POST", "/scaling/policies", json=scaling_policy)
print("Created scaling policy:", created_policy)

# Create a branch for vulnerability-fix changes in the specified repository.
repository_id = os.environ.get("REPOSITORY_ID")
if repository_id:
    branch = request(
        "POST",
        f"/repositories/{repository_id}/branches",
        json={
            "name": "vulnerability-fixes",
            "source_branch": os.environ.get("SOURCE_BRANCH", "main"),
        },
    )
    print("Created repository branch:", branch)

# Register the application access-control policy for vulnerability and resource updates.
access_control = {
    "application": {
        "name": "vulnerability-resource-management",
        "description": "Manage access to vulnerability findings and resource updates.",
    },
    "policy": {
        "allow": ["vulnerability:read", "resource:update"],
        "deny": [],
    },
}
access_control_result = request("POST", "/access-control", json=access_control)
print("Configured application access control:", access_control_result)

