import os
import requests

BASE_URL = "https://api.socbench.example"
API_KEY = os.getenv("SOCBENCH_API_KEY")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if API_KEY:
    session.headers.update({"X-API-Key": API_KEY})

# Retrieve latency measurements and performance metrics for each supported region.
latency_response = session.get(f"{BASE_URL}/metrics/latency", timeout=30)
latency_response.raise_for_status()
latency_data = latency_response.json()

regions_response = session.get(f"{BASE_URL}/regions/supported", timeout=30)
regions_response.raise_for_status()
regions_data = regions_response.json()

if isinstance(regions_data, dict):
    regions = regions_data.get("regions", [])
else:
    regions = regions_data

regional_metrics = []
for region in regions:
    if isinstance(region, dict):
        region_id = region.get("regionID") or region.get("id")
        region_name = region.get("name") or region.get("region")
    else:
        region_id = str(region)
        region_name = str(region)

    if not region_id:
        continue

    response = session.get(
        f"{BASE_URL}/regions/{region_id}/metrics",
        timeout=30,
    )
    if response.ok:
        regional_metrics.append(
            {"region": region_name, "metrics": response.json()}
        )

# Retrieve alerts, then fetch detailed information for each alert ID.
alerts_response = session.get(f"{BASE_URL}/alerts", timeout=30)
alerts_response.raise_for_status()
alerts_data = alerts_response.json()
alerts = alerts_data.get("alerts", []) if isinstance(alerts_data, dict) else alerts_data

alert_details = []
for alert in alerts:
    if not isinstance(alert, dict):
        continue
    alert_id = alert.get("alertID") or alert.get("alert_id")
    if not alert_id:
        continue

    response = session.get(
        f"{BASE_URL}/alerts/{alert_id}",
        timeout=30,
    )
    if response.ok:
        alert_details.append(response.json())

# Discover available and recommended distribution channels.
channels_response = session.get(
    f"{BASE_URL}/content-distribution",
    timeout=30,
)
channels_response.raise_for_status()
channels = channels_response.json()

recommendations_response = session.get(
    f"{BASE_URL}/recommendations",
    timeout=30,
)
recommendations_response.raise_for_status()
recommendations = recommendations_response.json()

# Build data-driven insights from the retrieved latency and channel information.
latency_text = str(latency_data.get("latency", ""))
try:
    latency_ms = float(latency_text.lower().replace("ms", "").strip())
except (TypeError, ValueError):
    latency_ms = None

regional_latencies = []
for item in regional_metrics:
    metrics = item["metrics"]
    value = metrics.get("latency")
    if value is not None:
        try:
            regional_latencies.append(
                (item["region"], float(str(value).lower().replace("ms", "").strip()))
            )
        except ValueError:
            pass

insights = {
    "network_latency": latency_data,
    "regional_metrics": regional_metrics,
    "alerts": alert_details,
    "available_channels": channels,
    "recommended_channels": recommendations,
    "observations": [],
}

if latency_ms is not None:
    insights["observations"].append(
        f"Current monitored network latency is {latency_ms:g} ms."
    )

if regional_latencies:
    highest_region, highest_latency = max(regional_latencies, key=lambda item: item[1])
    lowest_region, lowest_latency = min(regional_latencies, key=lambda item: item[1])
    insights["observations"].append(
        f"Highest regional latency is {highest_latency:g} ms in {highest_region}; "
        f"lowest is {lowest_latency:g} ms in {lowest_region}."
    )
    if highest_latency > 100:
        insights["observations"].append(
            "Prioritize investigation and capacity optimization in the highest-latency region."
        )

if alert_details:
    insights["observations"].append(
        f"{len(alert_details)} existing alert(s) have detailed records; review them "
        "alongside regional latency before broadcasting."
    )
else:
    insights["observations"].append(
        "No alert details were returned for the listed alerts."
    )

insights["observations"].append(
    "Compare available channels with the recommended channels and prioritize "
    "channels suited to regions with elevated latency."
)

print(insights)

import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

sensor_id = os.getenv("SENSOR_ID", "sensor_001")
start_date = os.getenv("START_DATE", "2026-01-01")
customer_ids = [
    customer_id.strip()
    for customer_id in os.getenv("CUSTOMER_IDS", "").split(",")
    if customer_id.strip()
]
alert_method = os.getenv("NOTIFICATION_METHOD", "email")
outdated_alert_id = os.getenv("OUTDATED_ALERT_ID")

# Retrieve incident history and identify disruptions involving the sensor.
history_response = session.get(f"{BASE_URL}/incident-history")
history_response.raise_for_status()
incident_history = history_response.json()

def contains_sensor(value, target):
    if isinstance(value, dict):
        return any(
            contains_sensor(key, target) or contains_sensor(item, target)
            for key, item in value.items()
        )
    if isinstance(value, list):
        return any(contains_sensor(item, target) for item in value)
    return target.lower() in str(value).lower()

incidents = incident_history if isinstance(incident_history, list) else incident_history.get(
    "incidents", []
)
related_incidents = [
    incident for incident in incidents if contains_sensor(incident, sensor_id)
]

# Verify the sensor's current operational status.
sensor_response = session.get(f"{BASE_URL}/status/{sensor_id}")
sensor_response.raise_for_status()
sensor_status = sensor_response.json()

# Fetch consumption summaries for customers affected by the related disruptions.
consumption_trends = {}
for customer_id in customer_ids:
    response = session.get(
        f"{BASE_URL}/consumption/summary",
        params={"customerId": customer_id, "startDate": start_date},
    )
    response.raise_for_status()
    consumption_trends[customer_id] = response.json()

# Configure peak usage alerts for the affected customers.
if alert_method not in {"email", "sms", "push"}:
    raise ValueError("NOTIFICATION_METHOD must be email, sms, or push")

peak_alerts = {}
for customer_id in customer_ids:
    response = session.post(
        f"{BASE_URL}/peak-alert",
        json={"customerId": customer_id, "notificationMethod": alert_method},
    )
    response.raise_for_status()
    peak_alerts[customer_id] = response.json() if response.content else None

# The documented API provides deletion for alert settings, not simulation scenarios.
# Delete the outdated incident-management alert setting when its ID is supplied.
deletion_result = None
if outdated_alert_id:
    response = session.delete(f"{BASE_URL}/alert-settings/{outdated_alert_id}")
    response.raise_for_status()
    deletion_result = response.status_code

result = {
    "related_incidents": related_incidents,
    "sensor_status": sensor_status,
    "consumption_trends": consumption_trends,
    "peak_alerts": peak_alerts,
    "outdated_alert_setting_deletion_status": deletion_result,
}
print(result)

